imal_handling"},{"id":"arcana"},{"id":"athletics"},{"id":"deception"},{"id":"history"},{"id":"insight"},{"id":"intimidation"},{"id":"investigation"},{"id":"medicine"},{"id":"nature"},{"id":"perception"},{"id":"performance"},{"id":"persuasion"},{"id":"religion"},{"id":"sleight_of_hand"},{"id":"stealth"},{"id":"survival"}]},"lore-skills":{"count":3,"skills":true,"options":[{"id":"acrobatics"},{"id":"animal_handling"},{"id":"arcana"},{"id":"athletics"},{"id":"deception"},{"id":"history"},{"id":"insight"},{"id":"intimidation"},{"id":"investigation"},{"id":"medicine"},{"id":"nature"},{"id":"perception"},{"id":"performance"},{"id":"persuasion"},{"id":"religion"},{"id":"sleight_of_hand"},{"id":"stealth"},{"id":"survival"}]}}}],"path_spells":[],"expanded_spells":[]}},{"class_id":"cleric","data":{"paths":[{"class_id":"cleric","id":"life","name":"Domínio da Vida","features":[{"id":"proficiencia-adicional","level":1,"name":"Proficiência adicional","description":"Ganha proficiência em armaduras pesadas."},{"id":"discipulo-da-vida","level":1,"name":"Discípulo da vida","description":"Magias de cura de 1º círculo ou maior curam +2 + círculo do espaço. A Mesa soma esse bônus ao dano/cura básico quando aplicável."},{"id":"preservar-a-vida","level":2,"name":"Preservar a vida","description":"Canalizar Divindade: distribua 5 × nível de clérigo PV entre criaturas em 9 m, até metade dos PV máximos de cada; não afeta construtos/mortos-vivos."},{"id":"curandeiro-abencoado","level":6,"name":"Curandeiro abençoado","description":"Ao curar outra criatura com magia de 1º círculo ou maior, você recupera 2 + círculo do espaço PV."},{"id":"golpe-divino","level":8,"name":"Golpe divino","description":"Uma vez em seu turno, ataque com arma causa +1d8 radiante; +2d8 no nível 14."},{"id":"cura-suprema","level":17,"name":"Cura suprema","description":"Quando rolar dados para cura de magia, use o máximo dos dados em vez de rolar."}],"level":1,"source":"SRD 5.1"},{"class_id":"cleric","id":"knowledge","name":"Domínio do Conhecimento","features":[{"level":1,"name":"Bênçãos do conhecimento","description":"Aprende dois idiomas e escolhe duas perícias entre Arcanismo, História, Natureza e Religião, com proficiência dobrada.","id":"bencaos-do-conhecimento"},{"level":2,"name":"Conhecimento das eras","description":"Canalizar Divindade: ganha proficiência temporária em uma perícia ou ferramenta por 10 minutos.","id":"conhecimento-das-eras"},{"level":6,"name":"Ler pensamentos","description":"Canalizar Divindade: sonda pensamentos com salvaguarda de SAB; pode encerrar para usar Sugestão sem gastar espaço.","id":"ler-pensamentos"},{"level":8,"name":"Conjuração potente","description":"Adiciona SAB ao dano de seus truques de clérigo.","id":"conjuracao-potente"},{"level":17,"name":"Visões do passado","description":"Medita para obter visões sobre um objeto ou local. Duração e alcance da informação dependem do contexto; recupera em descanso curto ou longo.","id":"visoes-do-passado"}],"level":1,"source":"Livro do Jogador (2014)"},{"class_id":"cleric","id":"light","name":"Domínio da Luz","features":[{"level":1,"name":"Truque adicional","description":"Aprende Luz, sem ocupar o limite de truques de clérigo.","id":"truque-adicional"},{"level":1,"name":"Labareda protetora","description":"Reação para impor desvantagem a um ataque de uma criatura vista a até 9 m; usos iguais a SAB, mínimo 1, por descanso longo.","id":"labareda-protetora"},{"level":2,"name":"Radiação do amanhecer","description":"Canalizar Divindade: dissipa escuridão mágica e causa 2d10 + nível de clérigo radiante em criaturas hostis a até 9 m; CON reduz à metade.","id":"radiacao-do-amanhecer"},{"level":6,"name":"Labareda aprimorada","description":"Sua reação protetora também pode defender outra criatura a até 9 m.","id":"labareda-aprimorada"},{"level":8,"name":"Conjuração potente","description":"Adiciona SAB ao dano dos truques de clérigo.","id":"conjuracao-potente"},{"level":17,"name":"Coroa de luz","description":"Ação para criar luz por 1 minuto. Inimigos na luz plena têm desvantagem contra suas magias de fogo ou radiantes; encerra com outra ação.","id":"coroa-de-luz"}],"level":1,"source":"Livro do Jogador (2014)"},{"class_id":"cleric","id":"nature","name":"Domínio da Natureza","features":[{"level":1,"name":"Acólito da natureza","description":"Escolhe um truque de druida e proficiência em Lidar com Animais, Natureza ou Sobrevivência; ganha armaduras pesadas.","id":"acolito-da-natureza"},{"level":2,"name":"Enfeitiçar animais e plantas","description":"Canalizar Divindade: bestas e plantas a até 9 m fazem salvaguarda de SAB contra encantamento por 1 minuto.","id":"enfeiticar-animais-e-plantas"},{"level":6,"name":"Amortecer elementos","description":"Reação para dar resistência a ácido, frio, fogo, elétrico ou trovejante a uma criatura a até 9 m para uma ocorrência de dano.","id":"amortecer-elementos"},{"level":8,"name":"Golpe divino","description":"Uma vez no seu turno, arma causa +1d8 de frio, fogo ou elétrico; +2d8 a partir do nível 14.","id":"golpe-divino"},{"level":17,"name":"Mestre da natureza","description":"Pode comandar, como ação bônus, criaturas afetadas pelo seu encantamento de animais e plantas.","id":"mestre-da-natureza"}],"level":1,"source":"Livro do Jogador (2014)"},{"class_id":"cleric","id":"tempest","name":"Domínio da Tempestade","features":[{"level":1,"name":"Proficiências da tempestade","description":"Ganha armas marciais e armaduras pesadas.","id":"proficiencias-da-tempestade"},{"level":1,"name":"Ira da tempestade","description":"Reação após ser atingido por criatura a até 1,5 m: 2d8 elétrico ou trovejante, DES reduz à metade. Usos SAB, mínimo 1, por descanso longo.","id":"ira-da-tempestade"},{"level":2,"name":"Ira destruidora","description":"Canalizar Divindade: maximiza uma rolagem de dano elétrico ou trovejante.","id":"ira-destruidora"},{"level":6,"name":"Golpe de relâmpago","description":"Dano elétrico em criatura Grande ou menor pode empurrá-la até 3 m.","id":"golpe-de-relampago"},{"level":8,"name":"Golpe divino","description":"Uma vez por turno, arma recebe +1d8 trovejante; +2d8 no nível 14.","id":"golpe-divino"},{"level":17,"name":"Filho da tempestade","description":"Recebe deslocamento de voo igual ao deslocamento de caminhada enquanto estiver ao ar livre.","id":"filho-da-tempestade"}],"level":1,"source":"Livro do Jogador (2014)"},{"class_id":"cleric","id":"trickery","name":"Domínio da Enganação","features":[{"level":1,"name":"Bênção do trapaceiro","description":"Ação para conceder vantagem em Furtividade a outra criatura por até 1 hora; afeta uma criatura por vez.","id":"bencao-do-trapaceiro"},{"level":2,"name":"Invocar duplicidade","description":"Canalizar Divindade: cria uma duplicata ilusória por 1 minuto, com concentração. Pode conjurar a partir dela; certas posições concedem vantagem.","id":"invocar-duplicidade"},{"level":6,"name":"Manto de sombras","description":"Canalizar Divindade: fica invisível até o fim do próximo turno ou até atacar ou conjurar.","id":"manto-de-sombras"},{"level":8,"name":"Golpe divino","description":"Uma vez por turno, arma recebe +1d8 de veneno; +2d8 no nível 14.","id":"golpe-divino"},{"level":17,"name":"Duplicidade aprimorada","description":"Invocar Duplicidade passa a criar até quatro duplicatas.","id":"duplicidade-aprimorada"}],"level":1,"source":"Livro do Jogador (2014)"},{"class_id":"cleric","id":"war","name":"Domínio da Guerra","features":[{"level":1,"name":"Proficiências de guerra","description":"Ganha armas marciais e armaduras pesadas.","id":"proficiencias-de-guerra"},{"level":1,"name":"Sacerdote da guerra","description":"Após usar Atacar, pode realizar um ataque com arma como ação bônus. Usos SAB, mínimo 1, por descanso longo.","id":"sacerdote-da-guerra"},{"level":2,"name":"Ataque dirigido","description":"Canalizar Divindade: adiciona +10 a uma jogada de ataque após rolar e antes de conhecer o resultado.","id":"ataque-dirigido"},{"level":6,"name":"Bênção do deus da guerra","description":"Reação e Canalizar Divindade para conceder +10 ao ataque de outra criatura a até 9 m.","id":"bencao-do-deus-da-guerra"},{"level":8,"name":"Golpe divino","description":"Uma vez por turno, arma recebe +1d8 do mesmo tipo de dano; +2d8 no nível 14.","id":"golpe-divino"},{"level":17,"name":"Avatar da batalha","description":"Resistência a dano cortante, perfurante e de concussão de armas não mágicas.","id":"avatar-da-batalha"}],"level":1,"source":"Livro do Jogador (2014)"}],"training":{"count":2,"skills":["history","insight","medicine","persuasion","religion"],"initial":["Armaduras leves e médias","Escudos","Armas simples"],"multi":["Armaduras leves e médias","Escudos"]},"requirements":[["wis"]],"subclass_level":1,"asi_levels":[4,8,12,16,19]},"grouped":{"choices":[{"keys":{"":["1:initial","1:multi","2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10:initial","10:multi","11:initial","11:multi","12:initial","12:multi","13:initial","13:multi","14:initial","14:multi","15:initial","15:multi","16:initial","16:multi","17:initial","17:multi","18:initial","18:multi","19:initial","19:multi","20:initial","20:multi"],"life":["1:initial","1:multi","2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10:initial","10:multi","11:initial","11:multi","12:initial","12:multi","13:initial","13:multi","14:initial","14:multi","15:initial","15:multi","16:initial","16:multi","17:initial","17:multi","18:initial","18:multi","19:initial","19:multi","20:initial","20:multi"],"light":["1:initial","1:multi","2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10:initial","10:multi","11:initial","11:multi","12:initial","12:mul