15:Pântano","15:Planície","15:Subterrâneo","16:","16:Ártico","16:Costa","16:Deserto","16:Floresta","16:Montanha","16:Pântano","16:Planície","16:Subterrâneo","17:","17:Ártico","17:Costa","17:Deserto","17:Floresta","17:Montanha","17:Pântano","17:Planície","17:Subterrâneo","18:","18:Ártico","18:Costa","18:Deserto","18:Floresta","18:Montanha","18:Pântano","18:Planície","18:Subterrâneo","19:","19:Ártico","19:Costa","19:Deserto","19:Floresta","19:Montanha","19:Pântano","19:Planície","19:Subterrâneo","20:","20:Ártico","20:Costa","20:Deserto","20:Floresta","20:Montanha","20:Pântano","20:Planície","20:Subterrâneo"]},"value":["Divine Favor","Shield of Faith","Magic Weapon","Spiritual Weapon","Crusader’s Mantle","Spirit Guardians","Freedom of Movement","Stoneskin","Flame Strike","Hold Monster"]}],"expanded_spells":[]}},{"class_id":"druid","data":{"paths":[{"class_id":"druid","id":"land","name":"Círculo da Terra","features":[{"id":"truque-adicional","level":2,"name":"Truque adicional","description":"Aprende mais um truque de druida."},{"id":"recuperacao-natural","level":2,"name":"Recuperação natural","description":"Após descanso curto, recupera espaços cuja soma dos círculos não excede metade do nível de druida arredondada para cima, sem círculos 6+. Um uso por descanso longo."},{"id":"magias-de-circulo","level":3,"name":"Magias de círculo","description":"Escolha o ambiente; recebe magias sempre preparadas nos níveis 3, 5, 7 e 9. Registre as magias do ambiente no grimório como extras."},{"id":"caminho-da-floresta","level":6,"name":"Caminho da floresta","description":"Ignora terreno difícil não mágico e vegetação comum; vantagem contra plantas mágicas que impedem movimento."},{"id":"protecao-natural","level":10,"name":"Proteção natural","description":"Imune a veneno/doença; elementais e fadas não podem enfeitiçar ou amedrontar você."},{"id":"santuario-natural","level":14,"name":"Santuário natural","description":"Animais e plantas que o atacam fazem SAB contra sua CD; falha obriga escolher outro alvo ou perder o ataque. A proteção cessa para a criatura se você a atacar."}],"level":2,"source":"SRD 5.1"},{"class_id":"druid","id":"moon","name":"Círculo da Lua","features":[{"level":2,"name":"Forma selvagem de combate","description":"Transforma-se como ação bônus; na forma animal, pode gastar espaço como ação bônus para recuperar 1d8 PV por círculo.","id":"forma-selvagem-de-combate"},{"level":2,"name":"Formas do círculo","description":"Pode usar bestas de ND 1; a partir do nível 6, ND até nível de druida dividido por 3. Restrições de natação e voo continuam seguindo o nível.","id":"formas-do-circulo"},{"level":6,"name":"Ataque primordial","description":"Ataques na forma animal contam como mágicos contra resistência e imunidade.","id":"ataque-primordial"},{"level":10,"name":"Forma selvagem elemental","description":"Pode gastar dois usos de Forma Selvagem para assumir forma de elemental do ar, terra, fogo ou água.","id":"forma-selvagem-elemental"},{"level":14,"name":"Mil formas","description":"Pode conjurar Alterar-se à vontade.","id":"mil-formas"}],"level":2,"source":"Livro do Jogador (2014)"}],"training":{"count":2,"skills":["arcana","animal_handling","insight","medicine","nature","perception","religion","survival"],"initial":["Armaduras leves e médias não metálicas","Escudos não metálicos","Armas druídicas","Kit de herbalismo"],"multi":["Armaduras leves e médias não metálicas","Escudos não metálicos"]},"requirements":[["wis"]],"subclass_level":2,"asi_levels":[4,8,12,16,19]},"grouped":{"choices":[{"keys":{"":["1:initial","1:multi","2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10:initial","10:multi","11:initial","11:multi","12:initial","12:multi","13:initial","13:multi","14:initial","14:multi","15:initial","15:multi","16:initial","16:multi","17:initial","17:multi","18:initial","18:multi","19:initial","19:multi","20:in