ura vista; ganha vantagem no próximo ataque corpo a corpo antes do fim do turno.","id":"passo-das-sombras"},{"level":11,"name":"Manto de sombras","description":"Ação para ficar invisível em penumbra ou escuridão, até atacar, conjurar ou entrar em luz plena.","id":"manto-de-sombras"},{"level":17,"name":"Oportunista","description":"Reação para atacar uma criatura a até 1,5 m quando outra criatura a atingir.","id":"oportunista"}],"level":3,"source":"Livro do Jogador (2014)"},{"class_id":"monk","id":"four-elements","name":"Caminho dos Quatro Elementos","features":[{"level":3,"name":"Discípulo dos elementos","description":"Aprende Sintonia Elemental e uma disciplina; aprende outra nos níveis 6, 11 e 17. Disciplinas usam ki e algumas permitem conjurar magias.","id":"discipulo-dos-elementos"},{"level":6,"name":"Disciplinas adicionais","description":"Aprende uma disciplina adicional. Pode substituir uma disciplina já conhecida ao aprender uma nova.","id":"disciplinas-adicionais"},{"level":11,"name":"Disciplinas superiores","description":"Aprende uma disciplina adicional e pode escolher opções com requisito de nível 11.","id":"disciplinas-superiores"},{"level":17,"name":"Maestria elemental","description":"Aprende uma disciplina adicional e pode escolher opções com requisito de nível 17. Limites de ki por magia: 3 até o nível 8, 4 até o 12, 5 até o 16 e 6 depois.","id":"maestria-elemental"}],"level":3,"source":"Livro do Jogador (2014)"}],"training":{"count":2,"skills":["acrobatics","athletics","history","insight","religion","stealth"],"initial":["Armas simples e espadas curtas","Uma ferramenta de artesão ou instrumento"],"multi":["Armas simples e espadas curtas"]},"requirements":[["dex"],["wis"]],"subclass_level":3,"asi_levels":[4,8,12,16,19]},"grouped":{"choices":[{"keys":{"":["1:initial","1:multi","2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10