ription":"Canalizar Divindade: ação, arma por 1 minuto soma CAR (mínimo +1) aos ataques e emite luz; é mágica se não era."},{"id":"expulsar-profanos","level":3,"name":"Expulsar profanos","description":"Canalizar Divindade: ínferos/mortos-vivos em 9 m fazem SAB ou são expulsos por 1 minuto ou até sofrer dano."},{"id":"aura-de-devocao","level":7,"name":"Aura de devoção","description":"Você e aliados em 3 m não podem ser enfeitiçados enquanto está consciente; 9 m no nível 18."},{"id":"pureza-de-espirito","level":15,"name":"Pureza de espírito","description":"Proteção contra o Bem e o Mal sempre ativa em você."},{"id":"aura-sagrada","level":20,"name":"Aura sagrada","description":"Ação: luz em 9 m por 1 minuto; inimigos que começam nessa área sofrem 10 radiante. Vantagem nas salvaguardas contra magias de ínferos/mortos-vivos. Um uso por descanso longo."}],"level":3,"source":"SRD 5.1"},{"class_id":"paladin","id":"ancients","name":"Juramento dos Anciões","features":[{"level":3,"name":"Canalizar divindade dos anciões","description":"Pode usar Ira da Natureza para conter uma criatura próxima, ou Expulsar os Infiéis contra fadas e corruptores.","id":"canalizar-divindade-dos-ancioes"},{"level":7,"name":"Aura de proteção mágica","description":"Você e aliados a até 3 m têm resistência a dano de magias; alcance de 9 m no nível 18.","id":"aura-de-protecao-magica"},{"level":15,"name":"Sentinela imortal","description":"Ao cair a 0 PV sem morrer, pode ficar com 1 PV, uma vez por descanso longo. Não sofre fragilidade da velhice e não envelhece por magia.","id":"sentinela-imortal"},{"level":20,"name":"Campeão ancestral","description":"Ação para transformar-se por 1 minuto: cura 10 PV no início de cada turno, conjura certas magias como ação bônus e dificulta salvaguardas próximas. Um uso por descanso longo.","id":"campeao-ancestral"}],"level":3,"source":"Livro do Jogador (2014)"},{"class_id":"paladin","id":"vengeance","name":"Juramento de Vingança","features":[{"level":3,"name":"Canalizar divindade da vingança","description":"Abjurar Inimigo impõe medo e limita movimento; Voto de Inimizade concede vantagem contra um alvo por 1 minuto.","id":"canalizar-divindade-da-vinganca"},{"level":7,"name":"Vingador implacável","description":"Ao acertar ataque de oportunidade, pode se mover até metade do deslocamento sem provocar oportunidades.","id":"vingador-implacavel"},{"level":15,"name":"Alma de vingança","description":"Reação para atacar o alvo do Voto de Inimizade quando ele realizar um ataque.","id":"alma-de-vinganca"},{"level":20,"name":"Anjo vingador","description":"Ação para transformação de 1 hora com voo de 18 m e aura de medo. Um uso por descanso longo.","id":"anjo-vingador"}],"level":3,"source":"Livro do Jogador (2014)"}],"training":{"count":2,"skills":["athletics","insight","intimidation","medicine","persuasion","religion"],"initial":["Todas as armaduras","Escudos","Armas simples e marciais"],"multi":["Armaduras leves e médias","Escudos","Armas simples e marciais"]},"requirements":[["str"],["cha"]],"subclass_level":3,"asi_levels":[4,8,12,16,19]},"grouped":{"choices":[{"keys":{"":["1:initial","1:multi"],"devotion":["1:initial","1:multi"],"ancients":["1:initial","1:multi"],"vengeance":["1:initial","1:multi"]},"value":{}},{"keys":{"":["2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10:initial","10:multi","11:initial","11:multi","12:initial","12:multi","13:initial","13:multi","14:initial","14:multi","15:initial","15:multi","16:initial","16:multi","17:initial","17:multi","18:initial","18:multi","19:initial","19:multi","20:initial","20:multi"],"devotion":["2:initial","2:multi","3:initial","3:multi","4:initial","4:multi","5:initial","5:multi","6:initial","6:multi","7:initial","7:multi","8:initial","8:multi","9:initial","9:multi","10:initial","10:multi","11:initial","11:multi","12:initial","12:multi","13:initial","13:multi","14