ue","id":"thief","name":"Ladrão","features":[{"id":"maos-rapidas","level":3,"name":"Mãos rápidas","description":"Ação Ardilosa também permite Prestidigitação, ferramentas de ladrão para armadilhas/fechaduras, ou Usar um Objeto."},{"id":"trabalho-no-segundo-andar","level":3,"name":"Trabalho no segundo andar","description":"Escalar não custa movimento adicional; salto longo aumenta em 0,3 × DES metros."},{"id":"furtividade-suprema","level":9,"name":"Furtividade suprema","description":"Vantagem em Furtividade se mover no máximo metade do deslocamento no turno."},{"id":"usar-instrumentos-magicos","level":13,"name":"Usar instrumentos mágicos","description":"Ignora requisitos de classe, raça e nível ao usar itens mágicos."},{"id":"reflexos-de-ladrao","level":17,"name":"Reflexos de ladrão","description":"No primeiro round de cada combate, dois turnos: sua iniciativa e iniciativa menos 10. Não funciona surpreendido; o mestre organiza a ordem."}],"level":3,"source":"SRD 5.1"},{"class_id":"rogue","id":"arcane-trickster","name":"Trapaceiro Arcano","features":[{"id":"conjuracao-de-arquetipo","level":3,"name":"Conjuração de arquétipo","description":"Inteligência, magias de mago; progressão de um terço. Restrições de escolas e habilidades complementares seguem o livro da mesa."},{"level":3,"name":"Mãos mágicas furtivas","description":"Aprende Mãos Mágicas; a mão pode ser invisível e realizar tarefas furtivas, como usar ferramentas de ladrão à distância.","id":"maos-magicas-furtivas"},{"level":9,"name":"Emboscada mágica","description":"Criatura da qual estiver escondido tem desvantagem na salvaguarda contra uma magia que você conjurar naquele turno.","id":"emboscada-magica"},{"level":13,"name":"Trapaceiro versátil","description":"Pode usar a mão mágica para distrair um alvo próximo dela, concedendo vantagem contra ele até o fim do turno.","id":"trapaceiro-versatil"},{"level":17,"name":"Ladrão de magias","description":"Reação para tentar negar uma magia que o afete e aprender a conjurá-la temporariamente, respeitando círculo e salvaguarda da habilidade.","id":"ladrao-de-magias"}],"level":3,"source":"Livro do Jogador (2014)"},{"class_id":"rogue","id":"assassin","name":"Assassino","features":[{"level":3,"name":"Proficiências do assassino","description":"Ganha proficiência com kit de disfarce e kit de venenos.","id":"proficiencias-do-assassino"},{"level":3,"name":"Assassinar","description":"Vantagem contra criaturas que ainda não agiram. Acertos contra uma criatura surpreendida são críticos; surpresa é definida pelo mestre.","id":"assassinar"},{"level":9,"name":"Especialista em infiltração","description":"Pode criar uma identidade falsa com 7 dias de trabalho e 25 PO, incluindo documentação e aparência social.","id":"especialista-em-infiltracao"},{"level":13,"name":"Impostor","description":"Após estudar fala, escrita ou comportamento por 3 horas, pode imitá-los; testes para sustentar o disfarce recebem vantagem.","id":"impostor"},{"level":17,"name":"Golpe mortal","description":"Ao acertar criatura surpreendida, ela faz salvaguarda de CON, CD 8 + DES + proficiência. Falha dobra o dano do ataque.","id":"golpe-mortal"}],"level":3,"source":"Livro do Jogador (2014)"}],"training":{"count":4,"skills":["acrobatics","athletics","deception","insight","intimidation","investigation","perception","performance","persuasion","sleight_of_hand","stealth"],"initial":["Armaduras leves","Armas simples, bestas de mão, espadas longas/curtas e rapieiras","Ferramentas de ladrão"],"multi":["Armaduras leves","Uma perícia da classe","Ferramentas de ladrão"]},"requirements":[["dex"]],"subclass_level":3,"asi_levels":[4,8,10,12,16,19]},"grouped":{"choices":[{"keys":{"":["1:initial","2:initial","3:initial","4:initial","5:initial"],"thief":["1:initial","2:initial","3:initial","4:initial","5:initial"],"arcane-trickster":["1:initial","2:initial","3:initial","4:initial","5:initial"],"assassin":["1:initial","2:initial","3:initial","4:initial","5:initial"]},"value":{"expertise-1":{