um tipo de dano após descanso curto/longo; resistência, exceto dano de armas mágicas/prateadas."},{"id":"lancar-no-inferno","level":14,"name":"Lançar no inferno","description":"Após acertar ataque, transporta alvo até fim do próximo turno; se não for ínfero sofre 10d10 psíquico. Um uso por descanso longo."}],"level":1,"source":"SRD 5.1"},{"class_id":"warlock","id":"archfey","name":"A Arquifada","features":[{"level":1,"name":"Presença feérica","description":"Ação: cubo de 3 m impõe encanto ou medo até o fim do seu próximo turno, com salvaguarda de SAB. Recupera em descanso curto ou longo.","id":"presenca-feerica"},{"level":6,"name":"Fuga das brumas","description":"Reação ao sofrer dano: fica invisível e teleporta até 18 m; invisibilidade dura até o próximo turno ou até atacar/conjurar. Recupera em descanso curto ou longo.","id":"fuga-das-brumas"},{"level":10,"name":"Defesas sedutoras","description":"Imunidade a encantamento; pode reagir para tentar devolver esse efeito à criatura que o provocou.","id":"defesas-sedutoras"},{"level":14,"name":"Delírio sombrio","description":"Ação: prende uma criatura em uma ilusão, encantada ou amedrontada, com concentração e salvaguarda de SAB. Um uso por descanso curto ou longo.","id":"delirio-sombrio"}],"level":1,"source":"Livro do Jogador (2014)"},{"class_id":"warlock","id":"great-old-one","name":"O Grande Antigo","features":[{"level":1,"name":"Mente desperta","description":"Pode comunicar-se telepaticamente com criaturas vistas a até 9 m, desde que elas compreendam algum idioma.","id":"mente-desperta"},{"level":6,"name":"Proteção entrópica","description":"Reação para impor desvantagem a um ataque; se errar, ganha vantagem no próximo ataque contra aquele alvo antes do fim do próximo turno. Recupera em descanso curto ou longo.","id":"protecao-entropica"},{"level":10,"name":"Escudo de pensamentos","description":"Seus pensamentos não podem ser lidos sem permissão. Resistência a dano psíquico; causar esse dano a você também afeta o agressor.","id":"escudo-de-pensamentos"},{"level":14,"name":"Criar servo","description":"Pode tocar humanoide incapacitado para enfeitiçá-lo, mantendo comunicação telepática no mesmo plano. O efeito termina por remoção apropriada ou nova utilização.","id":"criar-servo"}],"level":1,"source":"Livro do Jogador (2014)"}],"training":{"count":2,"skills":["arcana","deception","history","intimidation","investigation","nature","religion"],"initial":["Armaduras leves","Armas simples"],"multi":["Armaduras leves","Armas simples"]},"requirements":[["cha"]],"subclass_level":1,"asi_levels":[4,8,12,16,19]},"grouped":{"choices":[{"keys":{"":["1:initial","1:multi"],"fiend":["1:initial","1:multi"],"archfey":["1:initial","1:multi"],"great-old-one":["1:initial","1:multi"]},"value":{}},{"keys":{"":["2:initial","2:multi"],"fiend":["2:initial","2:multi"],"archfey":["2:initial","2:multi"],"great-old-one":["2:initial","2:multi"]},"value":{"invocations":{"count":2,"options":[{"id":"agonizing-blast"},{"id":"armor-shadows"},{"id":"beast-speech"},{"id":"beguiling"},{"id":"devil-sight"},{"id":"eldritch-sight"},{"id":"eldritch-spear"},{"id":"eyes-rune"},{"id":"fiendish-vigor"},{"id":"mask-many"},{"id":"misty-visions"},{"id":"repelling"},{"id":"voice-chain","pact":"chain"},{"id":"book-secrets","pact":"tome"},{"id":"thirsting-blade","level":5,"pact":"blade"},{"id":"one-shadows","level":5},{"id":"ascendant-step","level":9},{"id":"otherworldly-leap","level":9},{"id":"lifedrinker","level":12,"pact":"blade"},{"id":"visions-realms","level":15},{"id":"witch-sight","level":15}]}}},{"keys":{"":["3:initial","3:multi","4:initial","4:multi"],"fiend":["3:initial","3:multi","4:initial","4:multi"],"archfey":["3:initial","3:multi","4:initial","4:multi"],"great-old-one":["3:initial","3:multi","4:initial","4:multi"]},"value":{"pact":{"count":1,"options":[{"id":"chain"},{"id":"blade"},{"id":"tome"}]},"invocations":{"count":2,"options":[{"id":"agonizing-blast"},{"id":"armor-shadows"},{"id":"beast-speech"},{"id":"beguilin