"12:Floresta","12:Montanha","12:Pântano","12:Planície","12:Subterrâneo"]},"value":["Heroism","Shield","Branding Smite","Warding Bond","Aura of Vitality","Conjure Barrage"]},{"keys":{"battle-smith":["13:","13:Ártico","13:Costa","13:Deserto","13:Floresta","13:Montanha","13:Pântano","13:Planície","13:Subterrâneo","14:","14:Ártico","14:Costa","14:Deserto","14:Floresta","14:Montanha","14:Pântano","14:Planície","14:Subterrâneo","15:","15:Ártico","15:Costa","15:Deserto","15:Floresta","15:Montanha","15:Pântano","15:Planície","15:Subterrâneo","16:","16:Ártico","16:Costa","16:Deserto","16:Floresta","16:Montanha","16:Pântano","16:Planície","16:Subterrâneo"]},"value":["Heroism","Shield","Branding Smite","Warding Bond","Aura of Vitality","Conjure Barrage","Aura of Purity","Fire Shield"]},{"keys":{"battle-smith":["17:","17:Ártico","17:Costa","17:Deserto","17:Floresta","17:Montanha","17:Pântano","17:Planície","17:Subterrâneo","18:","18:Ártico","18:Costa","18:Deserto","18:Floresta","18:Montanha","18:Pântano","18:Planície","18:Subterrâneo","19:","19:Ártico","19:Costa","19:Deserto","19:Floresta","19:Montanha","19:Pântano","19:Planície","19:Subterrâneo","20:","20:Ártico","20:Costa","20:Deserto","20:Floresta","20:Montanha","20:Pântano","20:Planície","20:Subterrâneo"]},"value":["Heroism","Shield","Branding Smite","Warding Bond","Aura of Vitality","Conjure Barrage","Aura of Purity","Fire Shield","Banishing Smite","Mass Cure Wounds"]}],"expanded_spells":[]}}]$creation$::jsonb;entry jsonb;data jsonb;property text;expanded jsonb;features jsonb;
begin
 for entry in select value from jsonb_array_elements(seed) loop
  -- Base class features are unchanged since 017; retain the installed copy.
  select r.data->'features' into features from public.dnd_character_build_rules r where r.class_id=entry->>'class_id';
  if jsonb_typeof(features) is distinct from 'array' then raise exception 'Instale as migrações anteriores até a 035 antes da 036.';end if;
  data=(entry->'data')||jsonb_build_object('features',features);
  foreach property in array array['choices','path_spells','expanded_spells'] loop
   select coalesce(jsonb_object_agg(k.key||':'||s.key,g.value->'value'),'{}'::jsonb) into expanded
   from jsonb_array_elements(entry->'grouped'->property) g(value)
   cross join lateral jsonb_each(g.value->'keys') k
   cross join lateral jsonb_array_elements_text(k.value) s(key);
   data=data||jsonb_build_object(property,expanded);
  end loop;
  insert into public.dnd_character_build_rules(class_id,data) values(entry->>'class_id',data)
  on conflict(class_id) do update set data=excluded.data;
 end loop;
end $build_catalog$;

